{
  "name": "opencode-slack-bridge",
  "version": "1.0.2",
  "description": "Bridge opencode agent sessions to Slack: approval/question cards, status reactions, reply injection.",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "slack",
    "slack-bridge",
    "socket-mode"
  ],
  "type": "module",
  "license": "MIT",
  "main": "dist/index.js",
  "types": "dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    }
  },
  "files": [
    "dist"
  ],
  "repository": {
    "type": "git",
    "url": "git+https://github.com/devrkd/mentat.git",
    "directory": "packages/slack-bridge"
  },
  "homepage": "https://github.com/devrkd/mentat/tree/main/packages/slack-bridge",
  "bugs": {
    "url": "https://github.com/devrkd/mentat/issues"
  },
  "scripts": {
    "build": "node build.mjs",
    "typecheck": "tsc --noEmit",
    "test": "tsx --test test/*.test.ts",
    "prepublishOnly": "npm run build"
  },
  "dependencies": {
    "@slack/socket-mode": "^2.0.0",
    "@slack/web-api": "^7.0.0"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "1.18.33",
    "@opencode-ai/sdk": "1.18.33",
    "@slack/types": "^2.0.0",
    "@types/node": "24.12.2",
    "esbuild": "^0.25.0",
    "tsx": "^4.23.15",
    "typescript": "5.8.2"
  }
}
